+                (BLF_OBJTYPE_FLEXRAY_RCVMESSAGE_EX <= obj_type && obj_type <= BLF_OBJTYPE_MOST_STRESS) ||
+                (BLF_OBJTYPE_CAN_ERROR_EXT <= obj_type && obj_type <= BLF_OBJTYPE_CAN_DRIVER_ERROR_EXT) ||
